#!/usr/bin/env node
/**
 * MCP server generated by make-mcp (https://github.com/make-mcp/make-mcp).
 * The behaviour is driven by the files in ../data – regenerate them instead of editing by hand,
 * or customise this file freely: it has no dependency on the generator.
 */
import { existsSync, readFileSync } from "node:fs";
import { timingSafeEqual } from "node:crypto";
import { createServer as createHttpServer, type IncomingMessage, type ServerResponse } from "node:http";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { SSEServerTransport } from "@modelcontextprotocol/sdk/server/sse.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { StreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/streamableHttp.js";
import {
  CallToolRequestSchema,
  ListResourcesRequestSchema,
  ListResourceTemplatesRequestSchema,
  ListToolsRequestSchema,
  ReadResourceRequestSchema,
  type CallToolResult,
  type Resource,
  type ResourceTemplate,
  type Tool,
} from "@modelcontextprotocol/sdk/types.js";
import MiniSearch from "minisearch";

// ---------------------------------------------------------------------------
// Data
// ---------------------------------------------------------------------------

interface Library {
  name: string;
  title: string;
  version: string;
  license?: string;
  contentMode: "embedded" | "fetch-on-install";
}

interface Manifest {
  toolMode?: "endpoints" | "grouped";
  name: string;
  title: string;
  targetVersion: string;
  envPrefix: string;
  transport: "stdio" | "http";
  license?: string;
  generator: string;
  generatedAt: string;
  docs?: { contentMode: "embedded" | "fetch-on-install"; sources: { kind: string; url: string; ref?: string }[] };
  /** Whole-project server: several libraries, docs in data/corpus/<name>.json or the cache. */
  libraries?: Library[];
  symbols?: boolean;
  api?: boolean;
}

interface DocPage {
  path: string;
  title: string;
  section?: string;
  kind: "page" | "component";
  markdown: string;
  sourceUrl: string;
  /** Library the page belongs to (whole-project servers). */
  library?: string;
}

interface ChangeEntry {
  version: string;
  title: string;
  date?: string;
  markdown: string;
  sourceUrl: string;
}

interface ApiSymbol {
  name: string;
  kind: string;
  module: string;
  signature: string;
  doc?: string;
}

interface Param {
  name: string;
  in: "path" | "query" | "header" | "cookie";
  required: boolean;
  description?: string;
  schema: Record<string, unknown>;
}

interface Endpoint {
  id: string;
  method: string;
  path: string;
  summary?: string;
  description?: string;
  params: Param[];
  body?: { contentType: string; required: boolean; schema: Record<string, unknown> };
  tags: string[];
  deprecated: boolean;
  resource: boolean;
}

type AuthScheme =
  | { type: "none" }
  | { type: "apiKey"; in: "header" | "query" | "cookie"; name: string; envVar: string }
  | { type: "bearer"; envVar: string }
  | { type: "basic"; userEnvVar: string; passwordEnvVar: string }
  | { type: "oauth2"; tokenUrl?: string; scopes: string[]; tokenEnvVar: string; clientIdEnvVar: string; clientSecretEnvVar: string };

interface ApiSpec {
  title: string;
  baseUrl: string;
  versionStrategy: { type: "none" } | { type: "path"; default: string } | { type: "header" | "query"; name: string; default: string };
  auth: AuthScheme[];
  endpoints: Endpoint[];
}

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const readJson = <T>(path: string): T => JSON.parse(readFileSync(path, "utf8")) as T;
const manifest = readJson<Manifest>(join(root, "data/manifest.json"));
const log = (message: string) => process.stderr.write(`[${manifest.name}] ${message}\n`);

// One library for a single-target server; several (pages prefixed with "<library>/") for a whole-project server.
const multi = manifest.libraries !== undefined;
const libraries: Library[] =
  manifest.libraries ??
  (manifest.docs
    ? [{ name: manifest.name, title: manifest.title, version: manifest.targetVersion, license: manifest.license, contentMode: manifest.docs.contentMode }]
    : []);

/** Same location the `make-mcp refresh` command writes to. */
function corpusCachePath(lib: Library): string {
  const base = process.env.MAKE_MCP_CACHE_DIR ?? join(process.env.XDG_CACHE_HOME ?? join(homedir(), ".cache"), "make-mcp");
  return join(base, lib.name, lib.version, "corpus.json");
}

function loadDocs(): { pages: DocPage[]; changes: Map<string, ChangeEntry[]>; missing: string[] } {
  const pages: DocPage[] = [];
  const changes = new Map<string, ChangeEntry[]>();
  const missing: string[] = [];
  for (const lib of libraries) {
    const path = lib.contentMode === "embedded" ? join(root, multi ? `data/corpus/${lib.name}.json` : "data/corpus.json") : corpusCachePath(lib);
    if (!existsSync(path)) {
      missing.push(lib.title);
      continue;
    }
    const corpus = readJson<{ pages: DocPage[]; changes?: ChangeEntry[] }>(path);
    for (const page of corpus.pages) pages.push(multi ? { ...page, path: `${lib.name}/${page.path}`, library: lib.name } : page);
    if (corpus.changes?.length) changes.set(lib.name, corpus.changes);
  }
  return { pages, changes, missing };
}

// ---------------------------------------------------------------------------
// Docs tools
// ---------------------------------------------------------------------------

const loaded = loadDocs();
const pages = loaded.pages;
const changes = loaded.changes;
const refreshHint = `Run \`npm run refresh\` in ${root} (fetches it from the original source on this machine).`;
const docsError = loaded.missing.length > 0 && pages.length === 0 ? `Documentation has not been downloaded yet. ${refreshHint}` : undefined;
if (loaded.missing.length > 0) log(`Documentation not downloaded yet: ${loaded.missing.join(", ")}. ${refreshHint}`);
const symbols: Record<string, ApiSymbol[]> = manifest.symbols ? readJson<Record<string, ApiSymbol[]>>(join(root, "data/symbols.json")) : {};

const search = new MiniSearch<DocPage & { id: string }>({
  fields: ["title", "section", "markdown"],
  storeFields: ["path", "title", "section", "kind", "library"],
  searchOptions: { boost: { title: 4, section: 2 }, prefix: true, fuzzy: 0.2 },
});
search.addAll(pages.map((p) => ({ ...p, id: p.path })));
const components = pages.filter((p) => p.kind === "component");
const libraryList = libraries.map((l) => `${l.title} ${l.version}`).join(", ");
const libraryProperty: Record<string, object> = multi
  ? { library: { type: "string", enum: libraries.map((l) => l.name), description: "Only this library (see list_topics)" } }
  : {};

/** Orders versions like 1.2.3 < 1.10.0; pre-releases (1.0.0-rc.1, 1.0.0b1) before the release. Mirrors server.py. */
function versionKey(version: string): [number, number, number, number, string] {
  const m = /^v?(\d+)(?:\.(\d+))?(?:\.(\d+))?(.*)$/.exec(version.trim());
  if (!m) return [-1, 0, 0, 0, version];
  const rest = m[4] ?? "";
  return [Number(m[1]), Number(m[2] ?? 0), Number(m[3] ?? 0), /^[-.]?(a|b|rc|alpha|beta|dev|pre|canary|next)/i.test(rest) ? 0 : 1, rest];
}

function compareVersions(a: string, b: string): number {
  const ka = versionKey(a);
  const kb = versionKey(b);
  for (let i = 0; i < 4; i++) if (ka[i] !== kb[i]) return (ka[i] as number) - (kb[i] as number);
  return ka[4] < kb[4] ? -1 : ka[4] > kb[4] ? 1 : 0;
}

const libraryOf = (args: Record<string, unknown>) => (typeof args.library === "string" && args.library ? args.library : undefined);
const unknownLibrary = (name: string) => text(`Unknown library "${name}". Libraries: ${libraries.map((l) => l.name).join(", ")}.`, true);

const text = (value: string, isError = false): CallToolResult => ({ content: [{ type: "text", text: value }], ...(isError ? { isError } : {}) });

function snippet(markdown: string, query: string): string {
  const body = markdown.replace(/^#+\s.*$/m, "").trim();
  const index = body.toLowerCase().indexOf(query.toLowerCase().split(/\s+/)[0] ?? "");
  const start = Math.max(0, index - 80);
  return (start > 0 ? "…" : "") + body.slice(start, start + 320).replace(/\s+/g, " ") + "…";
}

function findPage(path: string): DocPage | undefined {
  const wanted = path.replace(/^docs:\/\/[^/]+\//, "").replace(/^\/+/, "");
  return pages.find((p) => p.path === wanted);
}

const docsTools: Tool[] = libraries.length
  ? [
      {
        name: "search_docs",
        description: multi
          ? `Full-text search in the documentation of ${libraryList} (the versions this project uses). Returns matching pages with paths for get_page.`
          : `Full-text search in the ${manifest.title} ${manifest.targetVersion} documentation. Returns matching pages with paths for get_page.`,
        inputSchema: {
          type: "object",
          properties: {
            query: { type: "string", description: "Search terms, e.g. a component, class name or concept" },
            limit: { type: "number", description: "Maximum results (default 5)" },
            ...libraryProperty,
          },
          required: ["query"],
        },
        annotations: { readOnlyHint: true, openWorldHint: false },
      },
      {
        name: "get_page",
        description: `Returns the full Markdown of a ${manifest.title} documentation page by path.`,
        inputSchema: { type: "object", properties: { path: { type: "string" } }, required: ["path"] },
        annotations: { readOnlyHint: true, openWorldHint: false },
      },
      {
        name: "list_topics",
        description: multi
          ? "Lists the documentation pages of one library grouped by section; without library it lists the libraries."
          : `Lists all ${manifest.title} documentation pages grouped by section.`,
        inputSchema: { type: "object", properties: { ...libraryProperty } },
        annotations: { readOnlyHint: true, openWorldHint: false },
      },
      ...(components.length > 0
        ? [
            {
              name: "get_component",
              description: `Returns usage, class names and examples for a ${manifest.title} component (${components
                .slice(0, 12)
                .map((c) => c.title)
                .join(", ")}${components.length > 12 ? ", …" : ""}).`,
              inputSchema: { type: "object" as const, properties: { name: { type: "string" }, ...libraryProperty }, required: ["name"] },
              annotations: { readOnlyHint: true, openWorldHint: false },
            },
          ]
        : []),
      ...(changes.size > 0
        ? [
            {
              name: "changes_since",
              description: `Release notes after a version${multi ? "" : ` of ${manifest.title}`}: what changed, breaking changes and migration guides – for upgrades. Covers releases published up to ${manifest.generatedAt.slice(0, 10)}.`,
              inputSchema: {
                type: "object" as const,
                properties: {
                  version: { type: "string", description: `Version you are upgrading from (default: the version this server was generated for${multi ? "" : `, ${manifest.targetVersion}`})` },
                  to: { type: "string", description: "Last version to include (default: newest known)" },
                  ...libraryProperty,
                },
              },
              annotations: { readOnlyHint: true, openWorldHint: false },
            },
          ]
        : []),
      ...(Object.keys(symbols).length > 0
        ? [
            {
              name: "get_signature",
              description: `Exact signature and doc comment of an exported function, class, type or constant of ${libraries
                .filter((l) => symbols[l.name])
                .map((l) => `${l.title} ${l.version}`)
                .join(", ")} – read from the installed package.`,
              inputSchema: {
                type: "object" as const,
                properties: { name: { type: "string", description: "Exported name, e.g. useState, BaseModel or Client.get" }, ...libraryProperty },
                required: ["name"],
              },
              annotations: { readOnlyHint: true, openWorldHint: false },
            },
          ]
        : []),
    ]
  : [];

function callDocsTool(name: string, args: Record<string, unknown>): CallToolResult | undefined {
  if (!docsTools.some((t) => t.name === name)) return undefined;
  if (docsError) return text(docsError, true);

  const library = libraryOf(args);
  if (library && !libraries.some((l) => l.name === library)) return unknownLibrary(library);

  if (name === "search_docs") {
    const query = String(args.query ?? "");
    const limit = Math.min(Number(args.limit ?? 5) || 5, 20);
    const hits = search.search(query, library ? { filter: (r) => r.library === library } : {}).slice(0, limit);
    if (hits.length === 0) return text(`No results for "${query}". Try list_topics.`);
    return text(
      hits
        .map((hit) => {
          const page = findPage(String(hit.path))!;
          const where = [page.library, page.section].filter(Boolean).join(" · ");
          return `## ${page.title}${where ? ` (${where})` : ""}\npath: ${page.path}\n${snippet(page.markdown, query)}`;
        })
        .join("\n\n"),
    );
  }
  if (name === "get_page") {
    const page = findPage(String(args.path ?? ""));
    return page ? text(`${page.markdown}\n\n_Source: ${page.sourceUrl}_`) : text(`Unknown path "${String(args.path)}". Use search_docs or list_topics.`, true);
  }
  if (name === "list_topics") {
    if (multi && !library) {
      const lines = libraries.map((l) => {
        const count = pages.filter((p) => p.library === l.name).length;
        return `- ${l.title} ${l.version} — library \`${l.name}\`, ${count ? `${count} pages` : "not downloaded yet"}${changes.has(l.name) ? ", release notes" : ""}${symbols[l.name] ? ", signatures" : ""}`;
      });
      return text(`# Libraries\n${lines.join("\n")}\n\nCall list_topics with library for its pages.`);
    }
    const groups = new Map<string, DocPage[]>();
    for (const page of pages.filter((p) => !library || p.library === library)) {
      groups.set(page.section ?? "General", [...(groups.get(page.section ?? "General") ?? []), page]);
    }
    return text([...groups].map(([section, list]) => `## ${section}\n${list.map((p) => `- ${p.title} — \`${p.path}\``).join("\n")}`).join("\n\n"));
  }
  if (name === "get_component") {
    const wanted = String(args.name ?? "").toLowerCase().trim();
    const exact = components.find(
      (c) => (!library || c.library === library) && (c.title.toLowerCase() === wanted || c.path.split("/").pop() === wanted.replace(/\s+/g, "-")),
    );
    if (exact) return text(`${exact.markdown}\n\n_Source: ${exact.sourceUrl}_`);
    const similar = search
      .search(wanted, { filter: (r) => r.kind === "component" && (!library || r.library === library) })
      .slice(0, 5)
      .map((r) => String(r.title));
    return text(`No component named "${String(args.name)}".${similar.length ? ` Did you mean: ${similar.join(", ")}?` : ""}`, true);
  }
  if (name === "changes_since") return changesSince(args, library);
  if (name === "get_signature") return getSignature(args, library);
  return undefined;
}

function changesSince(args: Record<string, unknown>, library: string | undefined): CallToolResult {
  const name = library ?? (changes.size === 1 ? [...changes.keys()][0] : undefined);
  if (!name) return text(`Pass library – release notes exist for: ${[...changes.keys()].join(", ")}.`, true);
  const entries = changes.get(name);
  const lib = libraries.find((l) => l.name === name)!;
  if (!entries) return text(`No release notes for ${lib.title}. Release notes exist for: ${[...changes.keys()].join(", ")}.`, true);
  const from = String(args.version || lib.version).replace(/^v/, "");
  const to = typeof args.to === "string" && args.to ? args.to.replace(/^v/, "") : undefined;
  const selected = entries.filter((e) => compareVersions(e.version, from) > 0 && (!to || compareVersions(e.version, to) <= 0));
  if (selected.length === 0) {
    return text(
      `No ${lib.title} release after ${from}${to ? ` up to ${to}` : ""} in this server's data. Newest known: ${entries[entries.length - 1]!.version} ` +
        `(collected ${manifest.generatedAt.slice(0, 10)} – regenerate the server for later releases).`,
    );
  }
  const guides = pages
    .filter((p) => (!multi || p.library === name) && /migrat|upgrad|breaking/i.test(`${p.title} ${p.path}`))
    .slice(0, 8)
    .map((p) => `- ${p.title} — \`${p.path}\``);
  const parts = [
    `# ${lib.title}: ${selected.length} release${selected.length === 1 ? "" : "s"} after ${from}${to ? ` up to ${to}` : ""}`,
    ...(guides.length ? [`Migration guides in the docs (get_page):\n${guides.join("\n")}`] : []),
  ];
  let size = parts.join("\n\n").length;
  let shown = 0;
  for (const e of selected) {
    const heading = e.title !== e.version && e.title !== `v${e.version}` ? `${e.version} – ${e.title}` : e.version;
    const block = `## ${heading}${e.date ? ` (${e.date})` : ""}\n${e.markdown}\n\n_Source: ${e.sourceUrl}_`;
    if (shown > 0 && size + block.length > MAX_RESPONSE_CHARS) break;
    parts.push(block);
    size += block.length;
    shown++;
  }
  if (shown < selected.length) {
    parts.push(`… ${selected.length - shown} later release${selected.length - shown === 1 ? "" : "s"} not shown – call again with version ${selected[shown - 1]!.version}.`);
  }
  return text(parts.join("\n\n"));
}

function getSignature(args: Record<string, unknown>, library: string | undefined): CallToolResult {
  const wanted = String(args.name ?? "").trim();
  const scope = library ? [library] : Object.keys(symbols);
  if (library && !symbols[library]) return text(`No API signatures for ${library}. Available for: ${Object.keys(symbols).join(", ")}.`, true);
  const all = scope.flatMap((lib) => (symbols[lib] ?? []).map((s) => ({ lib, s })));
  let hits = all.filter((c) => c.s.name === wanted);
  if (hits.length === 0) hits = all.filter((c) => c.s.name.toLowerCase() === wanted.toLowerCase());
  // Namespace members: "useState" finds "React.useState".
  if (hits.length === 0) hits = all.filter((c) => c.s.name.endsWith(`.${wanted}`));
  // TypeScript members ("Client.get") are part of their class or interface declaration.
  if (hits.length === 0 && wanted.includes(".")) hits = all.filter((c) => c.s.name === wanted.split(".")[0]);
  if (hits.length > 0) {
    return text(
      hits
        .slice(0, 5)
        .map(({ lib, s }) => {
          const language = /\.d\.[mc]?ts$/.test(s.module) ? "ts" : "python";
          return `## ${s.name} (${s.kind}${multi ? `, ${lib}` : ""})\nmodule: ${s.module}\n\n\`\`\`${language}\n${s.signature}\n\`\`\`${s.doc ? `\n\n${s.doc}` : ""}`;
        })
        .join("\n\n---\n\n"),
    );
  }
  const needle = wanted.toLowerCase();
  const similar = [...new Set(all.filter((c) => c.s.name.toLowerCase().includes(needle)).map((c) => c.s.name))].slice(0, 15);
  return text(`No exported symbol "${wanted}".${similar.length ? ` Similar: ${similar.join(", ")}.` : " Use search_docs for concepts and guides."}`, true);
}

// ---------------------------------------------------------------------------
// API tools
// ---------------------------------------------------------------------------

const api = manifest.api ? readJson<ApiSpec>(join(root, "data/api.json")) : undefined;
const env = (suffix: string) => process.env[`${manifest.envPrefix}_${suffix}`];
const MAX_RESPONSE_CHARS = 50_000;

if (api) {
  const missing = api.auth.flatMap((a) => {
    if (a.type === "apiKey" || a.type === "bearer") return process.env[a.envVar] ? [] : [a.envVar];
    if (a.type === "basic") return [a.userEnvVar, a.passwordEnvVar].filter((v) => !process.env[v]);
    if (a.type === "oauth2") return process.env[a.tokenEnvVar] || process.env[a.clientIdEnvVar] ? [] : [a.tokenEnvVar];
    return [];
  });
  if (missing.length > 0 && missing.length === api.auth.length) log(`No credentials configured. Set one of: ${missing.join(", ")}`);
}

function apiVersion(): string | undefined {
  if (!api || api.versionStrategy.type === "none") return undefined;
  return env("API_VERSION") ?? api.versionStrategy.default;
}

function baseUrl(): string {
  const base = env("BASE_URL") ?? api!.baseUrl;
  return base.replace("{apiVersion}", apiVersion() ?? "");
}

function toolSchema(ep: Endpoint): Tool["inputSchema"] {
  const properties: Record<string, object> = {};
  const required: string[] = [];
  for (const p of ep.params) {
    properties[p.name] = { ...p.schema, ...(p.description ? { description: p.description } : {}) };
    if (p.required) required.push(p.name);
  }
  if (ep.body) {
    properties.body = { ...ep.body.schema, description: `Request body (${ep.body.contentType})` };
    if (ep.body.required) required.push("body");
  }
  return { type: "object", properties, ...(required.length ? { required } : {}) };
}

const apiTools: Tool[] = (api?.endpoints ?? []).map((ep) => ({
  name: ep.id,
  description: [ep.summary, ep.description, `${ep.method.toUpperCase()} ${ep.path}`, ep.deprecated ? "(deprecated)" : ""]
    .filter(Boolean)
    .join("\n\n")
    .slice(0, 1024),
  inputSchema: toolSchema(ep),
  annotations: {
    readOnlyHint: ep.method === "get" || ep.method === "head",
    destructiveHint: ep.method === "delete",
    idempotentHint: ["get", "head", "put", "delete"].includes(ep.method),
    openWorldHint: true,
  },
}));

// Large APIs: three meta tools instead of one tool per operation keep the client's context small.
const grouped = manifest.toolMode === "grouped";
const endpointById = new Map((api?.endpoints ?? []).map((ep) => [ep.id, ep]));
const hasDestructive = (api?.endpoints ?? []).some((ep) => ep.method === "delete");

const groupedTools: Tool[] = [
  {
    name: "list_operations",
    description: `List ${api?.title ?? "API"} operations (id, method, path, summary). Filter by tag and/or keyword, then use describe_operation.`,
    inputSchema: {
      type: "object",
      properties: {
        tag: { type: "string", description: "Only operations with this tag" },
        query: { type: "string", description: "Keyword matched against id, path and summary" },
      },
    },
    annotations: { readOnlyHint: true, openWorldHint: false },
  },
  {
    name: "describe_operation",
    description: "Parameters, request body schema and description of one operation.",
    inputSchema: { type: "object", properties: { operation: { type: "string", description: "Operation id from list_operations" } }, required: ["operation"] },
    annotations: { readOnlyHint: true, openWorldHint: false },
  },
  {
    name: "call_operation",
    description: "Call an operation against the live API. Arguments follow the schema returned by describe_operation.",
    inputSchema: {
      type: "object",
      properties: {
        operation: { type: "string", description: "Operation id from list_operations" },
        arguments: { type: "object", description: "Path, query and header parameters by name, plus `body` for the request body" },
      },
      required: ["operation"],
    },
    annotations: { readOnlyHint: false, destructiveHint: hasDestructive, openWorldHint: true },
  },
];

function listOperations(args: Record<string, unknown>): CallToolResult {
  const tag = typeof args.tag === "string" ? args.tag.toLowerCase() : undefined;
  const query = typeof args.query === "string" ? args.query.toLowerCase() : undefined;
  const matches = (api?.endpoints ?? []).filter(
    (ep) =>
      (!tag || ep.tags.some((t) => t.toLowerCase() === tag)) &&
      (!query || [ep.id, ep.path, ep.summary ?? ""].some((s) => s.toLowerCase().includes(query))),
  );
  if (matches.length === 0) {
    const tags = [...new Set((api?.endpoints ?? []).flatMap((ep) => ep.tags))].sort();
    return text(`No operations match. Tags: ${tags.join(", ") || "none"}`);
  }
  const lines = matches.slice(0, 200).map((ep) => `${ep.id} – ${ep.method.toUpperCase()} ${ep.path}${ep.summary ? ` – ${ep.summary}` : ""}${ep.deprecated ? " (deprecated)" : ""}`);
  if (matches.length > lines.length) lines.push(`… ${matches.length - lines.length} more, narrow with tag or query`);
  return text(lines.join("\n"));
}

function describeOperation(id: unknown): CallToolResult {
  const ep = endpointById.get(String(id));
  if (!ep) return text(`Unknown operation: ${String(id)}. Use list_operations.`, true);
  const detail = {
    operation: ep.id,
    request: `${ep.method.toUpperCase()} ${ep.path}`,
    summary: ep.summary,
    description: ep.description,
    tags: ep.tags,
    deprecated: ep.deprecated || undefined,
    arguments: toolSchema(ep),
  };
  return text(JSON.stringify(detail, null, 2));
}

let oauthToken: { value: string; expiresAt: number } | undefined;

async function authorize(url: URL, headers: Record<string, string>): Promise<void> {
  for (const scheme of api?.auth ?? []) {
    if (scheme.type === "apiKey" && process.env[scheme.envVar]) {
      const value = process.env[scheme.envVar]!;
      if (scheme.in === "header") headers[scheme.name] = value;
      else if (scheme.in === "query") url.searchParams.set(scheme.name, value);
      else headers.cookie = `${headers.cookie ? `${headers.cookie}; ` : ""}${scheme.name}=${encodeURIComponent(value)}`;
      return;
    }
    if (scheme.type === "bearer" && process.env[scheme.envVar]) {
      headers.authorization = `Bearer ${process.env[scheme.envVar]}`;
      return;
    }
    if (scheme.type === "basic" && process.env[scheme.userEnvVar]) {
      const raw = `${process.env[scheme.userEnvVar]}:${process.env[scheme.passwordEnvVar] ?? ""}`;
      headers.authorization = `Basic ${Buffer.from(raw).toString("base64")}`;
      return;
    }
    if (scheme.type === "oauth2") {
      if (process.env[scheme.tokenEnvVar]) {
        headers.authorization = `Bearer ${process.env[scheme.tokenEnvVar]}`;
        return;
      }
      const clientId = process.env[scheme.clientIdEnvVar];
      if (scheme.tokenUrl && clientId) {
        if (!oauthToken || oauthToken.expiresAt < Date.now() + 30_000) {
          const res = await fetch(scheme.tokenUrl, {
            method: "POST",
            headers: { "content-type": "application/x-www-form-urlencoded" },
            body: new URLSearchParams({
              grant_type: "client_credentials",
              client_id: clientId,
              client_secret: process.env[scheme.clientSecretEnvVar] ?? "",
              ...(scheme.scopes.length ? { scope: scheme.scopes.join(" ") } : {}),
            }),
          });
          if (!res.ok) throw new Error(`OAuth token request failed with HTTP ${res.status}`);
          const token = (await res.json()) as { access_token: string; expires_in?: number };
          oauthToken = { value: token.access_token, expiresAt: Date.now() + (token.expires_in ?? 3600) * 1000 };
        }
        headers.authorization = `Bearer ${oauthToken.value}`;
        return;
      }
    }
  }
}

function encodeBody(contentType: string, body: unknown): BodyInit {
  if (contentType.includes("json")) return JSON.stringify(body);
  const entries = Object.entries((body ?? {}) as Record<string, unknown>).filter(([, v]) => v !== undefined);
  if (contentType.includes("multipart")) {
    const form = new FormData();
    for (const [key, value] of entries) form.append(key, typeof value === "string" ? value : JSON.stringify(value));
    return form;
  }
  if (contentType.includes("x-www-form-urlencoded")) {
    return new URLSearchParams(entries.map(([k, v]) => [k, typeof v === "string" ? v : JSON.stringify(v)]));
  }
  return typeof body === "string" ? body : JSON.stringify(body);
}

async function callEndpoint(ep: Endpoint, args: Record<string, unknown>): Promise<CallToolResult> {
  const path = ep.path.replace(/\{([^}]+)\}/g, (_, name: string) => {
    const value = args[name];
    if (value === undefined || value === null || value === "") throw new Error(`Missing path parameter "${name}"`);
    // "." and ".." would make the URL resolve to another endpoint than the one this tool describes.
    if (String(value) === "." || String(value) === "..") throw new Error(`Invalid path parameter "${name}"`);
    return encodeURIComponent(String(value));
  });
  const url = new URL(baseUrl().replace(/\/$/, "") + path);
  const headers: Record<string, string> = { accept: "application/json, text/plain;q=0.9, */*;q=0.5" };
  const strategy = api!.versionStrategy;
  if (strategy.type === "header") headers[strategy.name] = apiVersion()!;
  if (strategy.type === "query") url.searchParams.set(strategy.name, apiVersion()!);

  for (const p of ep.params) {
    const value = args[p.name];
    if (value === undefined || p.in === "path") continue;
    const serialized = typeof value === "string" ? value : JSON.stringify(value);
    if (p.in === "query") {
      if (Array.isArray(value)) value.forEach((v) => url.searchParams.append(p.name, String(v)));
      else url.searchParams.set(p.name, serialized);
    } else if (p.in === "header") headers[p.name] = serialized;
    else headers.cookie = `${headers.cookie ? `${headers.cookie}; ` : ""}${p.name}=${encodeURIComponent(serialized)}`;
  }

  await authorize(url, headers);
  let body: BodyInit | undefined;
  if (ep.body && args.body !== undefined) {
    body = encodeBody(ep.body.contentType, args.body);
    if (!ep.body.contentType.includes("multipart")) headers["content-type"] = ep.body.contentType;
  }

  const res = await fetch(url, { method: ep.method.toUpperCase(), headers, body, signal: AbortSignal.timeout(30_000) });
  let payload = await res.text();
  if ((res.headers.get("content-type") ?? "").includes("json")) {
    try {
      payload = JSON.stringify(JSON.parse(payload), null, 2);
    } catch {
      // keep raw text
    }
  }
  if (payload.length > MAX_RESPONSE_CHARS) payload = `${payload.slice(0, MAX_RESPONSE_CHARS)}\n… (truncated)`;
  return text(`HTTP ${res.status} ${res.statusText}\n\n${payload}`, !res.ok);
}

const resourceEndpoints = (api?.endpoints ?? []).filter((ep) => ep.resource);
const apiUri = (path: string) => `api://${manifest.name}${path}`;

function matchResource(uri: string): { ep: Endpoint; args: Record<string, string> } | undefined {
  for (const ep of resourceEndpoints) {
    const names: string[] = [];
    const pattern = new RegExp(
      `^${apiUri(ep.path)
        .replace(/[.*+?^$()|[\]\\]/g, "\\$&")
        .replace(/\\?\{([^}]+)\\?\}/g, (_, name: string) => {
          names.push(name);
          return "([^/]+)";
        })}$`,
    );
    const match = pattern.exec(uri);
    if (match) return { ep, args: Object.fromEntries(names.map((n, i) => [n, decodeURIComponent(match[i + 1] ?? "")])) };
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// MCP wiring
// ---------------------------------------------------------------------------

const instructions = [
  libraries.length
    ? `Documentation for ${multi ? libraryList : `${manifest.title} ${manifest.targetVersion}`}: use search_docs first${multi ? " (optionally with library)" : ""}, then get_page${components.length ? " or get_component" : ""}.`
    : "",
  changes.size > 0 ? "For upgrades: changes_since lists the release notes after a version." : "",
  Object.keys(symbols).length > 0 ? "For exact parameters and types: get_signature." : "",
  api
    ? grouped
      ? `${api.title} API (${api.endpoints.length} operations): list_operations → describe_operation → call_operation. Calls use the configured credentials.`
      : `${api.title} API (${api.endpoints.length} operations). Tools call the live API with the configured credentials.`
    : "",
]
  .filter(Boolean)
  .join(" ");

function createMcpServer(): Server {
  // The low-level Server is used on purpose: tool schemas come from data/api.json as JSON Schema.
  const server = new Server(
    { name: manifest.name, version: manifest.targetVersion },
    { capabilities: { tools: {}, resources: {} }, instructions },
  );

  server.setRequestHandler(ListToolsRequestSchema, async () => ({ tools: [...docsTools, ...(grouped ? groupedTools : apiTools)] }));

  server.setRequestHandler(CallToolRequestSchema, async (request) => {
    const args = (request.params.arguments ?? {}) as Record<string, unknown>;
    const docsResult = callDocsTool(request.params.name, args);
    if (docsResult) return docsResult;
    if (grouped && request.params.name === "list_operations") return listOperations(args);
    if (grouped && request.params.name === "describe_operation") return describeOperation(args.operation);
    const ep = grouped
      ? request.params.name === "call_operation"
        ? endpointById.get(String(args.operation))
        : undefined
      : endpointById.get(request.params.name);
    if (!ep) {
      return grouped && request.params.name === "call_operation"
        ? text(`Unknown operation: ${String(args.operation)}. Use list_operations.`, true)
        : text(`Unknown tool: ${request.params.name}`, true);
    }
    try {
      return await callEndpoint(ep, grouped ? ((args.arguments ?? {}) as Record<string, unknown>) : args);
    } catch (err) {
      return text(`Request failed: ${(err as Error).message}`, true);
    }
  });

  server.setRequestHandler(ListResourcesRequestSchema, async () => {
    const docResources: Resource[] = pages.slice(0, 500).map((p) => ({
      uri: `docs://${manifest.name}/${p.path}`,
      name: p.title,
      mimeType: "text/markdown",
    }));
    const apiResources: Resource[] = resourceEndpoints
      .filter((ep) => !ep.path.includes("{"))
      .map((ep) => ({ uri: apiUri(ep.path), name: ep.summary ?? ep.id, mimeType: "application/json" }));
    return { resources: [...docResources, ...apiResources] };
  });

  server.setRequestHandler(ListResourceTemplatesRequestSchema, async () => {
    const templates: ResourceTemplate[] = resourceEndpoints
      .filter((ep) => ep.path.includes("{"))
      .map((ep) => ({ uriTemplate: apiUri(ep.path), name: ep.summary ?? ep.id, mimeType: "application/json" }));
    if (libraries.length) templates.push({ uriTemplate: `docs://${manifest.name}/{path}`, name: "Documentation page", mimeType: "text/markdown" });
    return { resourceTemplates: templates };
  });

  server.setRequestHandler(ReadResourceRequestSchema, async (request) => {
    const { uri } = request.params;
    if (uri.startsWith(`docs://${manifest.name}/`)) {
      const page = findPage(uri);
      if (!page) throw new Error(`Unknown resource ${uri}`);
      return { contents: [{ uri, mimeType: "text/markdown", text: page.markdown }] };
    }
    const match = matchResource(uri);
    if (!match) throw new Error(`Unknown resource ${uri}`);
    const result = await callEndpoint(match.ep, match.args);
    const first = result.content[0];
    return { contents: [{ uri, mimeType: "application/json", text: first && first.type === "text" ? first.text : "" }] };
  });

  return server;
}

// ---------------------------------------------------------------------------
// Transports: stdio (default), Streamable HTTP, legacy SSE
// ---------------------------------------------------------------------------

const LOOPBACK = ["localhost", "127.0.0.1", "[::1]", "::1"];

/** Without a token only local callers are allowed: Host and Origin must be loopback, so web pages cannot reach the server via DNS rebinding. */
function isLocalRequest(req: IncomingMessage): boolean {
  const allowed = [...LOOPBACK, ...(process.env.MCP_ALLOWED_HOSTS ?? "").split(",").map((h) => h.trim().toLowerCase()).filter(Boolean)];
  const host = (req.headers.host ?? "").toLowerCase().replace(/:\d+$/, "");
  if (!allowed.includes(host)) return false;
  const origin = req.headers.origin;
  if (!origin) return true;
  try {
    return allowed.includes(new URL(origin).hostname.toLowerCase());
  } catch {
    return false;
  }
}

function isAuthorized(req: IncomingMessage): boolean {
  const token = process.env.MCP_AUTH_TOKEN;
  if (!token) return process.env.MCP_ALLOW_UNAUTHENTICATED === "1" || isLocalRequest(req);
  const given = Buffer.from(req.headers.authorization ?? "");
  const expected = Buffer.from(`Bearer ${token}`);
  return given.length === expected.length && timingSafeEqual(given, expected);
}

const MAX_BODY = 4 * 1024 * 1024;

async function readBody(req: IncomingMessage): Promise<unknown> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    size += (chunk as Buffer).length;
    if (size > MAX_BODY) throw Object.assign(new Error("request body too large"), { status: 413 });
    chunks.push(chunk as Buffer);
  }
  const raw = Buffer.concat(chunks).toString("utf8");
  return raw ? JSON.parse(raw) : undefined;
}

async function startHttp(legacySse: boolean): Promise<void> {
  const port = Number(process.env.PORT ?? 3000);
  const host = process.env.HOST ?? "127.0.0.1";
  const loopback = ["127.0.0.1", "localhost", "::1"].includes(host);
  if (!loopback && !process.env.MCP_AUTH_TOKEN && process.env.MCP_ALLOW_UNAUTHENTICATED !== "1") {
    log(`Refusing to listen on ${host} without MCP_AUTH_TOKEN. Set MCP_ALLOW_UNAUTHENTICATED=1 if access is controlled elsewhere (e.g. Cloud Run IAM).`);
    process.exit(1);
  }
  const sseSessions = new Map<string, SSEServerTransport>();

  const httpServer = createHttpServer(async (req: IncomingMessage, res: ServerResponse) => {
    const url = new URL(req.url ?? "/", `http://${req.headers.host ?? "localhost"}`);
    if (url.pathname === "/healthz") return void res.writeHead(200).end("ok");
    if (!isAuthorized(req)) return void res.writeHead(401).end("unauthorized");

    try {
      if (url.pathname === "/mcp") {
        if (req.method !== "POST") return void res.writeHead(405, { allow: "POST" }).end();
        // Stateless mode: a fresh server/transport per request scales to zero cleanly.
        const server = createMcpServer();
        const transport = new StreamableHTTPServerTransport({ sessionIdGenerator: undefined });
        res.on("close", () => {
          void transport.close();
          void server.close();
        });
        await server.connect(transport);
        await transport.handleRequest(req, res, await readBody(req));
        return;
      }
      if (legacySse && url.pathname === "/sse" && req.method === "GET") {
        const transport = new SSEServerTransport("/messages", res);
        sseSessions.set(transport.sessionId, transport);
        res.on("close", () => sseSessions.delete(transport.sessionId));
        await createMcpServer().connect(transport);
        return;
      }
      if (legacySse && url.pathname === "/messages" && req.method === "POST") {
        const transport = sseSessions.get(url.searchParams.get("sessionId") ?? "");
        if (!transport) return void res.writeHead(404).end("unknown session");
        await transport.handlePostMessage(req, res, await readBody(req));
        return;
      }
      res.writeHead(404).end();
    } catch (err) {
      log(`HTTP error: ${(err as Error).message}`);
      if (!res.headersSent) res.writeHead((err as { status?: number }).status ?? 500).end();
    }
  });

  await new Promise<void>((resolve) => httpServer.listen(port, host, resolve));
  log(`listening on http://${host}:${port}/mcp${legacySse ? " (legacy SSE on /sse)" : ""}`);
}

const transport = process.env.MCP_TRANSPORT ?? manifest.transport;
if (transport === "http" || transport === "sse") {
  await startHttp(transport === "sse");
} else {
  await createMcpServer().connect(new StdioServerTransport());
}
